import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { coursesAPI } from '../../services/api';

const Courses = () => {
  const [courses, setCourses] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all');

  useEffect(() => {
    const fetchCourses = async () => {
      try {
        const response = await coursesAPI.getAll();
        setCourses(response.data);
      } catch (error) {
        console.error('Error fetching courses:', error);
        // Use mock data for demo
        setCourses([
          {
            id: 1,
            title: 'React Fundamentals',
            description: 'Learn the basics of React development including components, state, and props',
            duration: '8 hours',
            level: 'Beginner',
            category: 'Frontend',
            instructor: 'John Doe',
            rating: 4.5,
            students: 1250
          },
          {
            id: 2,
            title: 'Node.js Backend Development',
            description: 'Build robust backend APIs with Node.js and Express',
            duration: '12 hours',
            level: 'Intermediate',
            category: 'Backend',
            instructor: 'Jane Smith',
            rating: 4.7,
            students: 890
          },
          {
            id: 3,
            title: 'Advanced JavaScript',
            description: 'Master advanced JavaScript concepts and ES6+ features',
            duration: '10 hours',
            level: 'Advanced',
            category: 'JavaScript',
            instructor: 'Mike Johnson',
            rating: 4.8,
            students: 2100
          },
          {
            id: 4,
            title: 'MongoDB Database Design',
            description: 'Learn to design and implement MongoDB databases',
            duration: '6 hours',
            level: 'Intermediate',
            category: 'Database',
            instructor: 'Sarah Wilson',
            rating: 4.6,
            students: 750
          },
          {
            id: 5,
            title: 'CSS Grid and Flexbox',
            description: 'Master modern CSS layout techniques',
            duration: '5 hours',
            level: 'Beginner',
            category: 'Frontend',
            instructor: 'Alex Brown',
            rating: 4.4,
            students: 1800
          },
          {
            id: 6,
            title: 'RESTful API Design',
            description: 'Learn to design and implement RESTful APIs',
            duration: '9 hours',
            level: 'Intermediate',
            category: 'Backend',
            instructor: 'David Lee',
            rating: 4.9,
            students: 1100
          }
        ]);
      } finally {
        setLoading(false);
      }
    };

    fetchCourses();
  }, []);

  const filteredCourses = filter === 'all' 
    ? courses 
    : courses.filter(course => course.category.toLowerCase() === filter.toLowerCase());

  const categories = ['all', ...new Set(courses.map(course => course.category))];

  if (loading) {
    return (
      <div className="main-content">
        <div className="text-center">
          <p>Loading courses...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="main-content">
      <div className="card">
        <div className="card-header">
          <h1 className="card-title">All Courses</h1>
          <p style={{ color: '#6c757d', margin: 0 }}>
            Explore our comprehensive collection of courses
          </p>
        </div>
      </div>

      {/* Filter */}
      <div className="card mb-3">
        <div style={{ display: 'flex', gap: '1rem', flexWrap: 'wrap' }}>
          {categories.map((category) => (
            <button
              key={category}
              onClick={() => setFilter(category)}
              className={`btn ${filter === category ? 'btn-primary' : 'btn-outline'}`}
              style={{ textTransform: 'capitalize' }}
            >
              {category}
            </button>
          ))}
        </div>
      </div>

      {/* Courses Grid */}
      <div className="grid grid-3">
        {filteredCourses.map((course) => (
          <div key={course.id} className="course-card">
            <div className="course-image">
              {course.title.charAt(0)}
            </div>
            <div className="course-content">
              <h3 className="course-title">{course.title}</h3>
              <p className="course-description">{course.description}</p>
              <div className="course-meta">
                <span>{course.duration}</span>
                <span>{course.level}</span>
              </div>
              <div style={{ 
                display: 'flex', 
                justifyContent: 'space-between', 
                alignItems: 'center',
                marginTop: '1rem',
                fontSize: '0.85rem',
                color: '#6c757d'
              }}>
                <span>⭐ {course.rating}</span>
                <span>{course.students} students</span>
              </div>
              <div style={{ 
                marginTop: '0.5rem',
                fontSize: '0.8rem',
                color: '#dc3545',
                fontWeight: '500'
              }}>
                {course.instructor}
              </div>
              <Link 
                to={`/courses/${course.id}`} 
                className="btn btn-outline"
                style={{ marginTop: '1rem', display: 'block', textAlign: 'center' }}
              >
                View Course
              </Link>
            </div>
          </div>
        ))}
      </div>

      {filteredCourses.length === 0 && (
        <div className="card text-center">
          <p style={{ color: '#6c757d' }}>No courses found in this category.</p>
        </div>
      )}
    </div>
  );
};

export default Courses;
